pub fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    if n <= 1 {
        return numbers;
    }

    // Compute 2*n - 1 safely in usize.
    let out_len = n
        .checked_mul(2)
        .and_then(|v| v.checked_sub(1))
        .expect("output length overflow");

    let mut result = Vec::with_capacity(out_len);

    // Insert delimiter only between elements.
    result.push(numbers[0]);
    for &x in numbers.iter().skip(1) {
        result.push(delimiter);
        result.push(x);
    }

    debug_assert_eq!(result.len(), out_len);
    result
}

